import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>好的水印应该保护作品，又不毁掉作品。这个平衡比看起来难：太淡的水印什么都保护不了，太重的水印会毁掉照片。</p>\n<p>最好的水印遵循几条简单规则，关于位置、透明度、大小和颜色。它们在你的作品里保持一致，在任何背景上都可读，而且不损坏图片就很难去掉。</p>\n<p>这篇文章把这些规则汇总到一处。包括标记放哪、做多强、选哪种样式，以及如何养成水印习惯，保护你发布的每一张图片。练手的时候，<a href=\"/zh/tianjia-shuiyin/\">图片水印工具</a>可以添加文字或 Logo 水印，拖动位置、调透明度都很方便。</p>\n<h2 id=\"why-watermarks-fail\">大多数水印为什么会失败</h2>\n<p>大多数水印失败是因为太胆小。10%透明度、放在遥远角落的标记，在大多数屏幕上都看不见，什么都保护不了。</p>\n<p>另一些失败是因为太激进。横穿照片中间的实色黑条，毁掉了客户用来判断照片的画面，也让每个观众都反感。</p>\n<p>还有一类败在位置上。空白角落里的角落标记等于邀请裁剪，盖在主体上的标记则遮住了照片本身要表达的东西。</p>\n<p>三种失败的解决办法都一样：先定目标，再按目标设置位置、透明度和大小。样片和品牌社交图需要的水印是不一样的。</p>\n<h2 id=\"placement-rules\">位置规则：角落、边缘与中央</h2>\n<p>角落是打品牌的标准位置。右下角一个小标记能表明图片归属，又不遮住主体，观众也习惯在那里找标志。</p>\n<p>边缘是中间选择。沿着底部边缘的标记看得见、不碍眼，而且比角落标记更难裁掉，因为裁掉边缘会去掉更多照片。</p>\n<p>中央是保护最强的位置。横穿中间的标记不毁掉图片就去不掉，这就是样片水印放在那里的原因。</p>\n<p>斜向位置结合了中央和角落的优点。45度穿过整个画面的标记既保护了图片，又让大部分主体保持可见。</p>\n<h2 id=\"opacity-rules\">透明度规则：多强才够</h2>\n<p>透明度是水印最重要的设置，也是最容易出错的那个。太淡没用，太强毁图。</p>\n<p>客户样片用30%到50%。标记清晰可读，能起到防盗作用，客户又能看清底下的照片。</p>\n<p>成品图片上的品牌水印用15%到25%。标志看得见，又不会抢主体风头。</p>\n<p>社交媒体用低的那一端。轻水印既打了品牌又不影响互动，重水印会让人滑走。</p>\n<h2 id=\"size-rules\">大小规则：够读，又够低调</h2>\n<p>水印要按图片会被查看的尺寸来定大小。全尺寸清晰的标记，在社交信息流的小预览里可能看不见。</p>\n<p>大小按图片百分比设置，不要按固定像素数。百分比设置让标记在缩略图和大幅打印上都保持一致。</p>\n<p>角落里的标志，宽度大约占图片宽度的10%到15%。够读，又不碍事。</p>\n<p>平铺图案用小一点的尺寸、宽一点的间距。重复的小标记能保护整张图片，又不会压住任何一个局部。</p>\n<h2 id=\"colour-and-contrast\">颜色与对比度：任何背景上都可读</h2>\n<p>白色文字适合深色背景，黑色文字适合浅色背景，但大多数照片两种背景都有。一种颜色总会在图片的某个地方消失。</p>\n<p>描边能解决这个问题。白色文字加细细的深色描边，在明亮天空上也能读；深色文字加浅色描边，在深色背景上也一样。</p>\n<p>淡淡的阴影是另一个选择。它把文字从背景上轻轻托起来，刚好够读，又没有描边的硬边缘。</p>\n<p>广泛使用之前，先在一张内容复杂的照片上测试标记。在白墙上清晰的水印，到了森林、人群或图案织物里可能就看不见了。</p>\n<h2 id=\"text-vs-logo\">文字还是标志：哪个更符合目标</h2>\n<p>文字最适合明确的归属声明。名字、年份和网址，图片归谁毫无疑问，而且文字做起来很快。</p>\n<p>标志最适合品牌。角落里一个小小的、可识别的标记，时间长了能建立熟悉感，客户看完整套作品集就认得出你的作品。</p>\n<p>图片很有价值时，两个一起用。角落里的标志下面写上网址，一次标记同时完成品牌和署名。</p>\n<p>标志保持简单。细节丰富、线条细的标志缩小到水印尺寸会变成一团模糊，粗壮简单的标记在任何地方都可读。</p>\n<h2 id=\"tiled-vs-single\">平铺图案与单个标记</h2>\n<p>单个标记适合打品牌。它以最小的干扰表明图片归属，适合用来看、用来分享的成品。</p>\n<p>平铺图案适合保护。它把标记重复铺满整张图片，任何裁剪都得不到干净副本，是客户样片的标准做法。</p>\n<p>代价是视觉噪音。平铺图案比单个标记更分散注意力，所以它属于样片，不属于你发布的最终图片。</p>\n<p>用平铺图案时降低透明度。30%重复的标记保护力已经很强，60%的同样图案会把底下的照片遮住。</p>\n<h2 id=\"branding-consistency\">全套作品的品牌一致性</h2>\n<p>一致的水印能建立辨识度。每张图片带着同样的标记、放在同样的位置，观众还没读名字就先认出了你的作品。</p>\n<p>标志、位置、透明度和大小，每张图片都保持相同。不一致的标记看起来像事后补的，而不是品牌。</p>\n<p>把设置写下来。一条简短的笔记，记着透明度、大小、角度和位置，隔了几个月也能做出同样的标记。</p>\n<p>每年检查一次标记。三年前看着现代的标志，现在可能已经过时了，刷新一下能让品牌保持当下的感觉。</p>\n<h2 id=\"proofs-workflow\">保护收入的样片流程</h2>\n<p>样片导出尺寸比成片小，长边1200像素左右。这样的样片够客户判断，打印却没法用。</p>\n<p>用平铺图案，透明度30%到40%，斜着放。这样既保护了整张图片，又不遮住客户要看的主体。</p>\n<p>发样片时附一句清楚的说明：带水印的版本只供挑选，干净文件在付款后交付。大多数客户一听就明白。</p>\n<p>发票结清后再交付干净的成片。带水印的样片留着，作为展示过什么、何时展示的记录。</p>\n<h2 id=\"social-media-marks\">社交媒体上的水印</h2>\n<p>社交平台上传时会压缩图片，淡淡的水印压缩后可能直接看不见。在下载回来的发布副本上测试标记。</p>\n<p>社交水印保持轻，放在主体附近，不要放在遥远的角落。角落标记在转发时很容易被裁掉，主体附近的标记能留下来。</p>\n<p>重水印会伤害互动。人们会滑过看着像广告的图片，所以轻品牌标记比重标记效果更好。</p>\n<p>想想社交媒体上是不是真的需要水印。如果目标是传播，一张干净的图片加图片说明里的名字，可能比带标记的图片表现更好。</p>\n<h2 id=\"print-and-watermarks\">水印与打印</h2>\n<p>最终打印文件永远不要加水印。屏幕上看着低调的标记，印出来可能强得多，因为打印的分辨率和对比度更高。</p>\n<p>水印只加在样片和预览图上。最终打印文件应该是干净的，付款后交付，不带任何会破坏效果的标记。</p>\n<p>发样片之前，按打印尺寸检查样片标记。手机上看着好的平铺图案，印成大幅样片可能很分散注意力。</p>\n<p>画廊打印的水印绝对不能出现在最终文件里。付了钱的客户期待一张干净的图片，上面有标记是对信任的辜负。</p>\n<h2 id=\"watermark-and-copyright\">水印与版权：法律怎么看</h2>\n<p>水印是威慑，不是法律护盾。它能清楚地表明归属，但代替不了版权登记或书面授权协议。</p>\n<p>它真正擅长的是让随手盗图变得没有意义。想找张干净图片用在自己网站上的人，看到带水印的版本，搜一下就能找到干净的替代品。</p>\n<p>它还有助于署名。没有署名被转发的照片，仍然带有你的名字或网址，观众能找到原始来源。</p>\n<p>留好原文件和带水印样片的记录。万一出现纠纷，带元数据的原文件比单独的水印有力得多。</p>\n<h2 id=\"testing-your-mark\">正式使用前测试水印</h2>\n<p>在三种照片上测试标记：深色的、明亮的、内容复杂的。三种都好用的水印，几乎在任何地方都好用。</p>\n<p>按图片会被分享的尺寸查看测试图。全尺寸清晰的标记，在小信息流预览里可能消失；按缩略图调好的标记，印大了可能占主导。</p>\n<p>请别人看一眼。新鲜的眼睛比制作者更快发现标记太淡、太重或位置不对，因为制作者早就知道上面写的是什么。</p>\n<p>平台压缩后也要测试。上传一张测试图片，下载回来，检查水印是否在压缩后还活着。</p>\n<h2 id=\"mistakes-to-avoid\">会削弱水印的错误</h2>\n<p>最常见的错误是把标记放在能被裁掉的位置。空白角落里的角落标记等于邀请裁剪，而不是保护。</p>\n<p>另一个错误是用带白底的标志。白框以矩形的样子盖在照片上，既不专业，又一眼就能看出来。</p>\n<p>还有人完全忘了加水印。一套干净无标记的作品集，等于把图片送给任何想重复使用它们的人，所以加水印要成为导出流程的一部分。</p>\n<p>最后，不要用水印写没人能读懂的文字。极小尺寸的手写体是装饰，不是保护，谁也认不出来。</p>\n<h2 id=\"watermark-habit\">养成水印习惯</h2>\n<p>把加水印作为每次导出的最后一步，不要偶尔想起来才做。成为流程的一部分后，没有任何图片会不带标记就离开你的电脑。</p>\n<p>在笔记里保存一套预设：标志文件、透明度、大小、角度、位置。一条简短的笔记能把五分钟的工作变成一分钟。</p>\n<p>样片和预览图默认加水印，干净的成片只在付款后交付。规则很简单，每项工作都能保护你的收入。</p>\n<p>每年检查一次水印，品牌变了就更新。标记和现在的标志与网址保持一致，作品看起来才专业。</p>\n<h2 id=\"watermarking-for-print-shops\">给打印店和冲印店的水印</h2>\n<p>打印店常常在大批量打印前要求看带水印的预览图。预览图让客户确认图片，干净文件则留在你手里，直到付款。</p>\n<p>打印预览图用平铺图案，因为单个角落标记很容易裁掉，而预览图可能印得很大。淡淡的重复图案在任何尺寸下都能保护图片。</p>\n<p>按实际打印尺寸检查预览图上的标记。手机屏幕上看着好的图案，印成大幅样片可能很分散注意力，所以发送前先测试。</p>\n<p>付款结清前，永远不要发送干净的打印文件。带水印的预览图是确认工具，干净文件是客户付钱买的产品。</p>\n<p>分步骤的操作见<a href=\"/zh/blog/ruhe-gei-tupian-jia-shuiyin/\">如何给图片加水印</a>。完整概览见<a href=\"/zh/blog/tupian-shuiyin-wanquan-zhinan/\">图片水印完全指南</a>；想加说明文字而不是水印，可以用<a href=\"/zh/tupian-tianjia-wenzi/\">图片加文字工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"水印放在照片的什么位置最安全？","answer":"中央或斜向位置最安全，因为那里的标记不毁掉照片就裁不掉。角落适合打品牌，但容易去掉。样片用中央，成品分享图用角落。"},{"question":"水印应该多明显？","answer":"客户样片用30%到50%的透明度：清晰可读，又不遮住照片。成品图片上的品牌水印，15%到25%就够了。低于10%的标记在大多数屏幕上都看不见，起不到保护作用。"},{"question":"水印里应该写网址吗？","answer":"目标是署名或引流时，应该写。观众看到无署名转发的照片，还能从标记找到你的网站。保持简短，比如只写域名，小尺寸下才可读。"},{"question":"平铺水印比单个水印好吗？","answer":"要保护的话，是的：平铺图案把标记重复铺满整张图片，任何裁剪都没法把所有标记都去掉。要打品牌的话，单个标记更好，视觉噪音更小。样片用平铺，成品用单个。"},{"question":"水印会影响照片的互动量吗？","answer":"重水印会，因为人们会滑过看着像广告的图片。角落里的轻水印对互动几乎没有影响。社交媒体的水印保持低调，放在主体附近，不要横穿中间。"},{"question":"免费分享的图片应该加水印吗？","answer":"通常不应该。免费资源上的重水印会劝退分享，违背了免费提供的初衷。想要署名的话，把名字写在图片说明或文件描述里，而不是标记在图片本身上。"}];
